import {describe, expect, it, jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and never calls the executor ([validated by registry validates input against inputSchema])', async () => {
      const registry = new ToolRegistry();
      const executeMock = jest.fn<() => Promise<string>>().mockResolvedValue('ok');

      const definition: ToolDefinition = {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'}
          },
          required: ['location']
        }
      };

      registry.register(definition, executeMock as any);

      const response = await registry.execute('weather', {});

      expect(executeMock).not.toHaveBeenCalled();
      expect(response.result).toMatch(/location.*required/i);
    });
  });
});
EOF
